import{_ as t,c as a,o as i,a2 as o}from"./chunks/framework.PGES7OoM.js";const m=JSON.parse(`{"title":"Compliance model","description":"","frontmatter":{"rawMarkdown":"# Compliance model\\n\\nCurvy's compliance model is two-sided, offering both pre-emptive compliance checks and retroactive compliance mechanisms.\\n\\n## Curvy ID with KYC\\n\\n> [!IMPORTANT]\\n> KYC for Curvy ID registration is only supported in [custom Curvy deployments for enterprises and institutions](../for-businesses/for-enterprises-and-institutions.md)\\n>\\n> **Curvy Web App and the canonical protocol do not feature Curvy ID with KYC.**\\n\\nKYC checks must pass prior to allowing a Curvy ID registration by the end-user.\\n\\nThis ensures a completely compliant set of users while respecting their privacy.\\n\\n## Pre-emptive compliance checks\\n\\nPre-emptive compliance checks allow trusted analytics vendors (Curvy is currently integrated with [Global Ledger](https://globalledger.io)) to provide a security and compliance score for a given address. This score is used by the Curvy-operated Portal Broadcaster to determine if a Portal can be deployed, allowing assets to be shielded.\\n\\n*These checks aim to prevent known malicious addresses involved in fraudulent activities from shielding funds with Curvy.*\\n\\n## Retroactive compliance checks\\n\\n> [!WARNING]\\n> Retroactive compliance checks are a WIP and are not yet publicly available for Curvy users.\\n\\nRetroactive compliance checks give us the ability for a trusted entity, such as a DAO or an analytics vendor, to *taint* (e.g., block access to protocol features) even after a malicious user has deposited and shielded their funds.\\n\\nThis is done through private and anonymized *shielding trail* that aims to preserve the chain of provenance of each Note inside the Privacy aggregator.\\n\\n**Successful tainting means that the user can only unshield the funds to the exact same address from which they were shielded, which is now tainted.**\\n","rawMarkdownPath":"/_raw/for-the-curious/compliance-model.md","rawMarkdownTitle":"Compliance model","rawMarkdownUrl":"https://docs.curvy.box/_raw/for-the-curious/compliance-model.md"},"headers":[],"relativePath":"for-the-curious/compliance-model.md","filePath":"for-the-curious/compliance-model.md","lastUpdated":1773768298000}`),r={name:"for-the-curious/compliance-model.md"};function s(n,e,c,l,d,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="compliance-model" tabindex="-1">Compliance model <a class="header-anchor" href="#compliance-model" aria-label="Permalink to &quot;Compliance model&quot;">​</a></h1><p>Curvy&#39;s compliance model is two-sided, offering both pre-emptive compliance checks and retroactive compliance mechanisms.</p><h2 id="curvy-id-with-kyc" tabindex="-1">Curvy ID with KYC <a class="header-anchor" href="#curvy-id-with-kyc" aria-label="Permalink to &quot;Curvy ID with KYC&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>KYC for Curvy ID registration is only supported in <a href="./../for-businesses/for-enterprises-and-institutions.html">custom Curvy deployments for enterprises and institutions</a></p><p><strong>Curvy Web App and the canonical protocol do not feature Curvy ID with KYC.</strong></p></div><p>KYC checks must pass prior to allowing a Curvy ID registration by the end-user.</p><p>This ensures a completely compliant set of users while respecting their privacy.</p><h2 id="pre-emptive-compliance-checks" tabindex="-1">Pre-emptive compliance checks <a class="header-anchor" href="#pre-emptive-compliance-checks" aria-label="Permalink to &quot;Pre-emptive compliance checks&quot;">​</a></h2><p>Pre-emptive compliance checks allow trusted analytics vendors (Curvy is currently integrated with <a href="https://globalledger.io" target="_blank" rel="noreferrer">Global Ledger</a>) to provide a security and compliance score for a given address. This score is used by the Curvy-operated Portal Broadcaster to determine if a Portal can be deployed, allowing assets to be shielded.</p><p><em>These checks aim to prevent known malicious addresses involved in fraudulent activities from shielding funds with Curvy.</em></p><h2 id="retroactive-compliance-checks" tabindex="-1">Retroactive compliance checks <a class="header-anchor" href="#retroactive-compliance-checks" aria-label="Permalink to &quot;Retroactive compliance checks&quot;">​</a></h2><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Retroactive compliance checks are a WIP and are not yet publicly available for Curvy users.</p></div><p>Retroactive compliance checks give us the ability for a trusted entity, such as a DAO or an analytics vendor, to <em>taint</em> (e.g., block access to protocol features) even after a malicious user has deposited and shielded their funds.</p><p>This is done through private and anonymized <em>shielding trail</em> that aims to preserve the chain of provenance of each Note inside the Privacy aggregator.</p><p><strong>Successful tainting means that the user can only unshield the funds to the exact same address from which they were shielded, which is now tainted.</strong></p>',14)])])}const u=t(r,[["render",s]]);export{m as __pageData,u as default};
